@startuml

class Well {
  + code : string
}

abstract class Company {
  + taxCode : string
  + numberOfEmployees() : int
}

interface OilCompany extends Company {}

interface OffshoreOilCompany extends Company {}

class OnshoreWell {
  + surfaceExtension : float
}

class OffshoreWell {
  + yearOfInstallation : int
  + geographicalAreaCode : string
  + environmentalImportance : int
}

class PollutionRate {
  + calculate() : double
}

OnshoreWell "1" -- "*" Company : extractsCrudeOilFrom
OffshoreWell "1" -- "*" Company : extractsCrudeOilFrom

Company "0..*" -- "1" OilCompany : is
Company "0..*" -- "1" OffshoreOilCompany : is

Well "1" -- "1" OnshoreWell : belongsTo
Well "1" -- "1" OffshoreWell : belongsTo

OnshoreWell "1" -- "*" PollutionRate : calculates
OffshoreWell "1" -- "*" PollutionRate : calculates

@enduml

